class Person {
  final String name;
  Person(this.name);
  String greet() => 'Hello $name';
}
String greeting(Person person) => person.greet();

import 'helper.dart';
import 'dart:typed_data';
void main() {
  final person = Person('Ada');
  final message = greeting(person);
  print(message.trim());
  print(Uint8List.fromList([65]));
}
